1	//! Product JSON profile: exact integers, scalar Unicode and bounded containers.
2	use alloc::{collections::BTreeMap, string::String, vec::Vec};
3	use core::fmt::{self, Write};
4	
5	pub const MAX_BYTES: usize = 4 * 1024 * 1024;
6	pub const MAX_DEPTH: usize = 32;
7	pub const MIN_INTEGER: i128 = -(1_i128 << 63);
8	pub const MAX_INTEGER: i128 = (1_i128 << 64) - 1;
9	
10	/// An exact admitted profile integer. Schema-specific narrower bounds follow.
11	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
12	pub struct Integer(i128);
13	
14	impl Integer {
15	    pub fn new(value: i128) -> Result<Self, Error> {
16	        if (MIN_INTEGER..=MAX_INTEGER).contains(&value) {
17	            Ok(Self(value))
18	        } else {
19	            Err(Error::IntegerRange)
20	        }
21	    }
22	
23	    pub fn get(self) -> i128 {
24	        self.0
25	    }
26	}
27	
28	/// An inert exact JSON value. Constructing one is not schema or Run admission.
29	#[derive(Clone, Debug, PartialEq, Eq)]
30	pub enum Value {
31	    Null,
32	    Bool(bool),
33	    Integer(Integer),
34	    String(String),
35	    Array(Vec<Value>),
36	    Object(BTreeMap<String, Value>),
37	}
38	
39	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
40	pub enum Error {
41	    ByteLimit,
42	    DepthLimit,
43	    InvalidUtf8,
44	    InvalidJson,
45	    InvalidUnicode,
46	    DuplicateKey,
47	    NegativeZero,
48	    IntegerRange,
49	    FloatForbidden,
50	}
51	
52	impl fmt::Display for Error {
53	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
54	        write!(f, "{self:?}")
55	    }
56	}
57	
58	impl core::error::Error for Error {}
59	
60	/// Reject lexical violations before any lossy deserialization can occur.
61	pub fn parse(raw: &[u8]) -> Result<Value, Error> {
62	    if raw.len() > MAX_BYTES {
63	        return Err(Error::ByteLimit);
64	    }
65	    core::str::from_utf8(raw).map_err(|_| Error::InvalidUtf8)?;
66	    let mut parser = Parser { raw, pos: 0 };
67	    let value = parser.value(0)?;
68	    parser.whitespace();
69	    if parser.pos != raw.len() {
70	        return Err(Error::InvalidJson);
71	    }
72	    Ok(value)
73	}
74	
75	struct Parser<'a> {
76	    raw: &'a [u8],
77	    pos: usize,
78	}
79	
80	impl Parser<'_> {
81	    fn whitespace(&mut self) {
82	        while matches!(self.raw.get(self.pos), Some(b' ' | b'\n' | b'\r' | b'\t')) {
83	            self.pos += 1;
84	        }
85	    }
86	
87	    fn consume(&mut self, byte: u8) -> bool {
88	        if self.raw.get(self.pos) == Some(&byte) {
89	            self.pos += 1;
90	            true
91	        } else {
92	            false
93	        }
94	    }
95	
96	    fn value(&mut self, containers: usize) -> Result<Value, Error> {
97	        self.whitespace();
98	        match self.raw.get(self.pos).copied() {
99	            Some(b'n') => self.literal(b"null", Value::Null),
100	            Some(b't') => self.literal(b"true", Value::Bool(true)),
101	            Some(b'f') => self.literal(b"false", Value::Bool(false)),
102	            Some(b'"') => self.string().map(Value::String),
103	            Some(b'-' | b'0'..=b'9') => self.integer().map(Value::Integer),
104	            Some(b'[' | b'{') if containers == MAX_DEPTH => Err(Error::DepthLimit),
105	            Some(b'[') => self.array(containers + 1),
106	            Some(b'{') => self.object(containers + 1),
107	            _ => Err(Error::InvalidJson),
108	        }
109	    }
110	
111	    fn literal(&mut self, text: &[u8], value: Value) -> Result<Value, Error> {
112	        if self.raw[self.pos..].starts_with(text) {
113	            self.pos += text.len();
114	            Ok(value)
115	        } else {
116	            Err(Error::InvalidJson)
117	        }
118	    }
119	
120	    fn integer(&mut self) -> Result<Integer, Error> {
121	        let start = self.pos;
122	        let negative = self.consume(b'-');
123	        if self.consume(b'0') {
124	            if self.raw.get(self.pos).is_some_and(u8::is_ascii_digit) {
125	                return Err(Error::InvalidJson);
126	            }
127	        } else {
128	            if !matches!(self.raw.get(self.pos), Some(b'1'..=b'9')) {
129	                return Err(Error::InvalidJson);
130	            }
131	            while self.raw.get(self.pos).is_some_and(u8::is_ascii_digit) {
132	                self.pos += 1;
133	            }
134	        }
135	        if matches!(self.raw.get(self.pos), Some(b'.' | b'e' | b'E')) {
136	            return Err(Error::FloatForbidden);
137	        }
138	        if negative && &self.raw[start..self.pos] == b"-0" {
139	            return Err(Error::NegativeZero);
140	        }
141	        // UTF-8 was checked at entry, and this range contains only ASCII digits.
142	        let token =
143	            core::str::from_utf8(&self.raw[start..self.pos]).map_err(|_| Error::InvalidJson)?;
144	        Integer::new(token.parse::<i128>().map_err(|_| Error::IntegerRange)?)
145	    }
146	
147	    fn string(&mut self) -> Result<String, Error> {
148	        if !self.consume(b'"') {
149	            return Err(Error::InvalidJson);
150	        }
151	        let mut result = String::new();
152	        let mut chunk = self.pos;
153	        loop {
154	            let byte = *self.raw.get(self.pos).ok_or(Error::InvalidJson)?;
155	            if byte == b'"' || byte == b'\\' {
156	                result.push_str(
157	                    core::str::from_utf8(&self.raw[chunk..self.pos])
158	                        .map_err(|_| Error::InvalidUtf8)?,
159	                );
160	                self.pos += 1;
161	                if byte == b'"' {
162	                    return Ok(result);
163	                }
164	                let escaped = *self.raw.get(self.pos).ok_or(Error::InvalidJson)?;
165	                self.pos += 1;
166	                match escaped {
167	                    b'"' => result.push('"'),
168	                    b'\\' => result.push('\\'),
169	                    b'/' => result.push('/'),
170	                    b'b' => result.push('\u{8}'),
171	                    b'f' => result.push('\u{c}'),
172	                    b'n' => result.push('\n'),
173	                    b'r' => result.push('\r'),
174	                    b't' => result.push('\t'),
175	                    b'u' => {
176	                        let high = self.hex4()?;
177	                        let scalar = if (0xd800..=0xdbff).contains(&high) {
178	                            if !self.consume(b'\\') || !self.consume(b'u') {
179	                                return Err(Error::InvalidUnicode);
180	                            }
181	                            let low = self.hex4()?;
182	                            if !(0xdc00..=0xdfff).contains(&low) {
183	                                return Err(Error::InvalidUnicode);
184	                            }
185	                            0x10000 + ((u32::from(high) - 0xd800) << 10) + u32::from(low) - 0xdc00
186	                        } else {
187	                            u32::from(high)
188	                        };
189	                        result.push(char::from_u32(scalar).ok_or(Error::InvalidUnicode)?);
190	                    }
191	                    _ => return Err(Error::InvalidJson),
192	                }
193	                chunk = self.pos;
194	            } else if byte < 0x20 {
195	                return Err(Error::InvalidJson);
196	            } else {
197	                self.pos += 1;
198	            }
199	        }
200	    }
201	
202	    fn hex4(&mut self) -> Result<u16, Error> {
203	        let mut value = 0_u16;
204	        for _ in 0..4 {
205	            let byte = *self.raw.get(self.pos).ok_or(Error::InvalidJson)?;
206	            self.pos += 1;
207	            let digit = match byte {
208	                b'0'..=b'9' => byte - b'0',
209	                b'a'..=b'f' => byte - b'a' + 10,
210	                b'A'..=b'F' => byte - b'A' + 10,
211	                _ => return Err(Error::InvalidJson),
212	            };
213	            value = value * 16 + u16::from(digit);
214	        }
215	        Ok(value)
216	    }
217	
218	    fn array(&mut self, containers: usize) -> Result<Value, Error> {
219	        self.pos += 1;
220	        self.whitespace();
221	        let mut items = Vec::new();
222	        if self.consume(b']') {
223	            return Ok(Value::Array(items));
224	        }
225	        loop {
226	            items.push(self.value(containers)?);
227	            self.whitespace();
228	            if self.consume(b']') {
229	                return Ok(Value::Array(items));
230	            }
231	            if !self.consume(b',') {
232	                return Err(Error::InvalidJson);
233	            }
234	        }
235	    }
236	
237	    fn object(&mut self, containers: usize) -> Result<Value, Error> {
238	        self.pos += 1;
239	        self.whitespace();
240	        let mut items = BTreeMap::new();
241	        if self.consume(b'}') {
242	            return Ok(Value::Object(items));
243	        }
244	        loop {
245	            self.whitespace();
246	            let key = self.string()?;
247	            if items.contains_key(&key) {
248	                return Err(Error::DuplicateKey);
249	            }
250	            self.whitespace();
251	            if !self.consume(b':') {
252	                return Err(Error::InvalidJson);
253	            }
254	            items.insert(key, self.value(containers)?);
255	            self.whitespace();
256	            if self.consume(b'}') {
257	                return Ok(Value::Object(items));
258	            }
259	            if !self.consume(b',') {
260	                return Err(Error::InvalidJson);
261	            }
262	        }
263	    }
264	}
265	
266	/// Encode C(X), preserving array order and validating programmatic inputs too.
267	pub fn encode(value: &Value) -> Result<Vec<u8>, Error> {
268	    let mut encoder = Encoder { bytes: Vec::new() };
269	    encoder.value(value, 0)?;
270	    Ok(encoder.bytes)
271	}
272	
273	struct Encoder {
274	    bytes: Vec<u8>,
275	}
276	
277	impl Encoder {
278	    fn append(&mut self, raw: &[u8]) -> Result<(), Error> {
279	        if raw.len() > MAX_BYTES - self.bytes.len() {
280	            return Err(Error::ByteLimit);
281	        }
282	        self.bytes.extend_from_slice(raw);
283	        Ok(())
284	    }
285	
286	    fn string(&mut self, value: &str) -> Result<(), Error> {
287	        self.append(b"\"")?;
288	        for scalar in value.chars() {
289	            match scalar {
290	                '"' => self.append(b"\\\"")?,
291	                '\\' => self.append(b"\\\\")?,
292	                '\u{8}' => self.append(b"\\b")?,
293	                '\u{c}' => self.append(b"\\f")?,
294	                '\n' => self.append(b"\\n")?,
295	                '\r' => self.append(b"\\r")?,
296	                '\t' => self.append(b"\\t")?,
297	                '\0'..='\u{1f}' => {
298	                    const HEX: &[u8] = b"0123456789abcdef";
299	                    let byte = scalar as u8;
300	                    self.append(&[
301	                        b'\\',
302	                        b'u',
303	                        b'0',
304	                        b'0',
305	                        HEX[usize::from(byte >> 4)],
306	                        HEX[usize::from(byte & 15)],
307	                    ])?;
308	                }
309	                _ => self.append(scalar.encode_utf8(&mut [0; 4]).as_bytes())?,
310	            }
311	        }
312	        self.append(b"\"")
313	    }
314	
315	    fn value(&mut self, value: &Value, containers: usize) -> Result<(), Error> {
316	        match value {
317	            Value::Null => self.append(b"null"),
318	            Value::Bool(true) => self.append(b"true"),
319	            Value::Bool(false) => self.append(b"false"),
320	            Value::Integer(number) => {
321	                let mut decimal = String::new();
322	                write!(decimal, "{}", number.get()).map_err(|_| Error::InvalidJson)?;
323	                self.append(decimal.as_bytes())
324	            }
325	            Value::String(value) => self.string(value),
326	            Value::Array(_) | Value::Object(_) if containers == MAX_DEPTH => Err(Error::DepthLimit),
327	            Value::Array(values) => {
328	                self.append(b"[")?;
329	                for (index, value) in values.iter().enumerate() {
330	                    if index != 0 {
331	                        self.append(b",")?;
332	                    }
333	                    self.value(value, containers + 1)?;
334	                }
335	                self.append(b"]")
336	            }
337	            Value::Object(values) => {
338	                self.append(b"{")?;
339	                // Rust String ordering is lexical UTF-8 byte ordering.
340	                for (index, (key, value)) in values.iter().enumerate() {
341	                    if index != 0 {
342	                        self.append(b",")?;
343	                    }
344	                    self.string(key)?;
345	                    self.append(b":")?;
346	                    self.value(value, containers + 1)?;
347	                }
348	                self.append(b"}")
349	            }
350	        }
351	    }
352	}
