7	#[test]
8	fn independent_canonical_byte_vectors() {
9	    // Literal byte goldens from the approved UR-1..5 contract, not this encoder.
10	    let vectors = [
11	        (
12	            " { \"𐀀\" : 1, \"\u{e000}\" : 0 } ",
13	            "{\"\u{e000}\":0,\"𐀀\":1}",
14	        ),
15	        (
16	            "[0,-1,-9223372036854775808,18446744073709551615]",
17	            "[0,-1,-9223372036854775808,18446744073709551615]",
18	        ),
19	        (r#"{"s":"e\u0301"}"#, "{\"s\":\"e\u{301}\"}"),
20	        (r#"{"s":"\u00e9"}"#, "{\"s\":\"é\"}"),
21	        (
22	            r#"{"s":"\/\b\f\n\r\t\u0001\"\\é"}"#,
23	            r#"{"s":"/\b\f\n\r\t\u0001\"\\é"}"#,
24	        ),
25	        (
26	            r#"["\u007f","\u2028","\ud800\udc00"]"#,
27	            "[\"\u{7f}\",\"\u{2028}\",\"𐀀\"]",
28	        ),
29	        (" [3,1,3] ", "[3,1,3]"),
30	        (
31	            "{\"z\":null,\"b\":true,\"a\":false}",
32	            "{\"a\":false,\"b\":true,\"z\":null}",
33	        ),
34	    ];
35	    for (input, expected) in vectors {
36	        let value = canonical::parse(input.as_bytes()).unwrap();
37	        let actual = canonical::encode(&value).unwrap();
38	        assert_eq!(actual, expected.as_bytes(), "{input}");
39	        assert_eq!(canonical::parse(&actual).unwrap(), value);
40	    }
41	}
