43	#[test]
44	fn lexical_integer_refusals_precede_rounding() {
45	    for input in [
46	        "1.0",
47	        "1e0",
48	        "1E0",
49	        "1.0000000000000001",
50	        "9007199254740991.1",
51	        "-1.0",
52	        "-0e0",
53	    ] {
54	        assert_eq!(
55	            canonical::parse(input.as_bytes()),
56	            Err(Error::FloatForbidden),
57	            "{input}"
58	        );
59	    }
60	    assert_eq!(canonical::parse(b"-0"), Err(Error::NegativeZero));
61	    for input in [
62	        "18446744073709551616",
63	        "-9223372036854775809",
64	        "999999999999999999999999999999999999999999999",
65	    ] {
66	        assert_eq!(
67	            canonical::parse(input.as_bytes()),
68	            Err(Error::IntegerRange),
69	            "{input}"
70	        );
71	    }
72	    assert_ne!(
73	        canonical::parse(b"true").unwrap(),
74	        canonical::parse(b"1").unwrap()
75	    );
76	    assert_ne!(
77	        canonical::parse(b"\"1\"").unwrap(),
78	        canonical::parse(b"1").unwrap()
79	    );
80	    assert_eq!(
81	        Integer::new(canonical::MIN_INTEGER - 1),
82	        Err(Error::IntegerRange)
83	    );
84	    assert_eq!(
85	        Integer::new(canonical::MAX_INTEGER + 1),
86	        Err(Error::IntegerRange)
87	    );
88	}
