90	#[test]
91	fn duplicate_keys_are_compared_after_escape_decoding() {
92	    for input in [
93	        r#"{"a":1,"a":2}"#,
94	        r#"{"a":1,"\u0061":2}"#,
95	        r#"{"𐀀":1,"\ud800\udc00":2}"#,
96	        r#"{"outer":{"a":1,"a":2}}"#,
97	    ] {
98	        assert_eq!(
99	            canonical::parse(input.as_bytes()),
100	            Err(Error::DuplicateKey),
101	            "{input}"
102	        );
103	    }
104	    // Unicode normalization is intentionally absent.
105	    assert!(canonical::parse("{\"é\":1,\"e\u{301}\":2}".as_bytes()).is_ok());
106	}
