156	#[test]
157	fn depth_counts_containers_but_not_scalar_leaves_or_keys() {
158	    for depth in [31, 32, 33] {
159	        let raw = format!("{}0{}", "[".repeat(depth), "]".repeat(depth));
160	        assert_eq!(canonical::parse(raw.as_bytes()).is_ok(), depth <= 32);
161	        let raw = format!("{}\"leaf\"{}", "{\"key\":".repeat(depth), "}".repeat(depth));
162	        assert_eq!(canonical::parse(raw.as_bytes()).is_ok(), depth <= 32);
163	    }
164	    let mut value = Value::Null;
165	    for _ in 0..32 {
166	        value = Value::Array(vec![value]);
167	    }
168	    assert!(canonical::encode(&value).is_ok());
169	    assert_eq!(
170	        canonical::encode(&Value::Array(vec![value])),
171	        Err(Error::DepthLimit)
172	    );
173	}
