175	#[test]
176	fn byte_limits_are_inclusive_and_apply_to_encoded_values() {
177	    let mut input = vec![b' '; MAX_BYTES];
178	    input[0] = b'0';
179	    assert!(canonical::parse(&input).is_ok());
180	    input.push(b' ');
181	    assert_eq!(canonical::parse(&input), Err(Error::ByteLimit));
182	    let value = Value::String("x".repeat(MAX_BYTES - 2));
183	    assert_eq!(canonical::encode(&value).unwrap().len(), MAX_BYTES);
184	    assert_eq!(
185	        canonical::encode(&Value::String("x".repeat(MAX_BYTES - 1))).map(|bytes| bytes.len()),
186	        Err(Error::ByteLimit)
187	    );
188	    // This programmatic input expands by six bytes per control plus two quotes.
189	    assert_eq!(
190	        canonical::encode(&Value::String("\0".repeat(MAX_BYTES / 6)))
191	            .unwrap()
192	            .len(),
193	        (MAX_BYTES / 6) * 6 + 2
194	    );
195	    assert_eq!(
196	        canonical::encode(&Value::String("\0".repeat(MAX_BYTES / 6 + 1))).map(|bytes| bytes.len()),
197	        Err(Error::ByteLimit)
198	    );
199	}
